import{showPhoto}from './photo-visuals.js?v=20261023-physicscomplete01';import{photoTasks,factorData,comparisonDirection,inverseIntensity,pondTrials,pondRates,mean,gasRate,greenhousePlans,netReturn,conservedPhoto,validPhotoAnswer}from './photo-models.js?v=20261023-physicscomplete01';import{photoTable}from './photo-figures.js?v=20261023-physicscomplete01';export{showPhoto};
export function mountPhoto(l,p,root,{save,done,feedback}){let w=p.widget,tasks=photoTasks[l.widget.slice(6)];w.photoTask??=0;w.photoDrafts??={};w.photoPassed??=[];let index=w.photoTask%tasks.length,t=tasks[index],v=w.photoDrafts[index]??={state:0,answer:'',seen:[]},$=s=>root.querySelector(s);const field=(id,label,opts,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${opts.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`,number=(id,label,value)=>`<label class="field-label" for="${id}">${label}</label><input class="lab-input" id="${id}" type="number" step="any" value="${value??''}">`,near=(x,a)=>x!==''&&x!==undefined&&Number.isFinite(Number(x))&&Math.abs(Number(x)-a)<.001;let body='',draw=()=>{},record=()=>true,valid=()=>false,help='';
if(t.type==='compare'){body=field('photoState','Compare model state',t.states.map((s,i)=>[i,s[1]]),v.state)+field('photoPrediction',t.prompt,t.choices.map((s,i)=>[i,s]),v.answer)+'<button class="secondary" id="revealPhoto">Reveal comparison →</button><p id="photoReadout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.state;showPhoto(t.scene,{kind:t.scene,state:t.states[v.state][0],revealed:r,title:t.title,stateLabel:t.states[v.state][1],result:r?t.results[v.state]:''});$('#photoReadout').textContent=r?t.results[v.state]:'Predict before revealing.';};record=()=>{if(v.revealed!==v.state||!validPhotoAnswer(t,v.state,v.answer)){feedback(t.why+' Predict and reveal the comparison before recording.',true);return false;}if(!v.seen.includes(v.state))v.seen.push(v.state);return true;};valid=()=>v.seen.length===t.states.length;help=t.why;}
else if(t.type==='equation'){body='<p>Cross-topic conservation scaffold: set coefficients for CO₂ + H₂O → C₆H₁₂O₆ + O₂, using one glucose molecule. Light is written above the arrow.</p>'+number('coefCO2','CO₂ coefficient',v.coefCO2)+number('coefWater','H₂O coefficient',v.coefWater)+number('coefGlucose','Glucose coefficient',v.coefGlucose)+number('coefOxygen','O₂ coefficient',v.coefOxygen)+field('reactionEnergy','Light supplies…',[['energy','Energy transferred into chloroplasts'],['atoms','New material atoms']],v.reactionEnergy)+'<button class="secondary" id="revealLedger">Inspect conserved inventory →</button><p id="photoReadout"></p>';draw=()=>{showPhoto('ledger:'+(v.ledgerRevealed?'after':'before'),{title:t.title,stateLabel:v.ledgerRevealed?'After · same C/H/O inventory':'Before · reactant inventory'});$('#photoReadout').textContent=v.ledgerRevealed?'Both sides:6C,12H,18O. Substances change; light transfers energy.':'Choose the coefficients and energy role before inspecting.';};valid=()=>v.ledgerRevealed&&conservedPhoto(Number(v.coefCO2),Number(v.coefWater),Number(v.coefGlucose),Number(v.coefOxygen))&&v.reactionEnergy==='energy';help='Use6CO₂ +6H₂O →1C₆H₁₂O₆ +6O₂. Count each element; light transfers energy rather than creating atoms.';}
else if(t.type==='factor'){let f=factorData[t.factor];v.factorIndex??=2;body='<p>Original single-factor dataset; other conditions suitable. Compare with the reference at '+f.x[2]+f.unit+' (rate'+f.y[2]+' model units). Record the lowest, reference and highest settings.</p>'+field('factorIndex',f.name+' / '+f.unit,f.x.map((x,i)=>[i,x]),v.factorIndex)+field('factorPrediction','Compared with the reference, predict rate',[['increase','Higher'],['decrease','Lower'],['same','Same']],v.factorPrediction)+'<button class="secondary" id="revealFactor">Reveal comparison →</button><p id="photoReadout"></p>'+field('factorReason','Mechanism',[['light','Light energy; response may flatten'],['reactant','CO₂ supplies a reactant'],['enzyme','Enzyme activity; high heat can denature'],['absorb','Chlorophyll absorbs useful light']],v.factorReason);draw=()=>{let r=v.factorRevealed===v.factorIndex;showPhoto('factor:'+t.factor,{factor:t.factor,index:r?v.factorIndex:2,title:t.title,stateLabel:r?f.x[v.factorIndex]+f.unit+' · rate'+f.y[v.factorIndex]:'Reference condition'});$('#photoReadout').textContent=r?'Selected rate:'+f.y[v.factorIndex]+' model units. '+f.why:'Predict before revealing the selected condition.';};record=()=>{if(v.factorRevealed!==v.factorIndex||v.factorPrediction!==comparisonDirection(f.y[v.factorIndex],f.y[2])||v.factorReason!==f.reason){feedback(f.why+' Compare the selected rate with the stated reference and match its mechanism.',true);return false;}if(!v.seen.includes(v.factorIndex))v.seen.push(v.factorIndex);return true;};valid=()=>[0,2,f.x.length-1].every(i=>v.seen.includes(i));help=f.why+' Record the lowest, reference and highest settings.';}
else if(t.type==='inverse'){v.distance??=10;body='<p>Idealised point-source approximation: intensity100 at10cm; I₂=100×(10/d₂)². This predicts relative light intensity, not automatically photosynthesis rate. Record10,20 and40cm.</p>'+field('lampDistance','Lamp distance / cm',[10,20,30,40].map(d=>[d,d]),v.distance)+number('inverseValue','Predicted relative intensity',v.inverseValue)+'<button class="secondary" id="revealInverse">Compare calculated intensity →</button><p id="photoReadout"></p>';draw=()=>{showPhoto('lamp',{distance:v.distance,title:t.title,stateLabel:'Distance'+v.distance+'cm'});$('#photoReadout').textContent=v.inverseRevealed===v.distance?'Calculated relative intensity:'+inverseIntensity(v.distance).toFixed(3)+'. Biological rate may respond differently.':'Calculate before revealing.';};record=()=>{if(v.inverseRevealed!==v.distance||!near(v.inverseValue,inverseIntensity(v.distance))){feedback('Use100×(10/d)² and keep distance units matched. Double distance means quarter intensity; enter to3 decimal places if needed.',true);return false;}if(!v.seen.includes(v.distance))v.seen.push(v.distance);return true;};valid=()=>[10,20,40].every(d=>v.seen.includes(d));help='Compare all required distances. This is a light approximation under stated assumptions, not a universal biological-rate equation.';}
else if(t.type==='economics'){v.plan??='baseline';body='<p>Original data for one matched period. Revenue and cost are £; rate is arbitrary. Inspect every plan, then choose maximum net return.</p>'+field('greenhousePlan','Inspect plan',greenhousePlans.map(p=>[p.id,p.name]),v.plan)+'<button class="secondary" id="inspectPlan">Record plan evidence →</button><p id="photoReadout"></p>'+field('bestPlan','Best net return',greenhousePlans.map(p=>[p.id,p.name]),v.bestPlan)+number('bestProfit','Selected plan profit / £',v.bestProfit)+field('profitReason','Decision criterion',[['net','Revenue minus cost, not rate alone'],['rate','Highest rate regardless of cost']],v.profitReason);draw=()=>{let a=greenhousePlans.find(p=>p.id===v.plan);showPhoto('greenhouse',{plan:v.plan,title:t.title,stateLabel:a.name});$('#photoReadout').textContent='Revenue£'+a.revenue+' · cost£'+a.cost+' · rate'+a.rate;};valid=()=>greenhousePlans.every(p=>v.seen.includes(p.id))&&v.bestPlan==='co2'&&near(v.bestProfit,85)&&v.profitReason==='net';help='Calculate revenue−cost for every plan. Extra CO₂ gives£85, whereas all three inputs give the highest rate but only£68 net return.';}
else if(t.type==='plan'){body=field('practicalVariable','Independent variable',[['light','Light via controlled lamp distance'],['all','Light, CO₂ and species changed together']],v.practicalVariable)+field('practicalControls','Matched controls',[['match','Temperature, CO₂, organism/length, time'],['none','No matched conditions']],v.practicalControls)+field('practicalMeasure','Measurement plan',[['repeat','Acclimatise; timed oxygen volume; repeats'],['one','One un-timed bubble glance']],v.practicalMeasure)+field('practicalSafety','Heat/electrical/glassware preparation',[['safe','Monitor heat; suitable setup; school supervision'],['unsafe','Unprotected electrics beside spills']],v.practicalSafety);draw=()=>showPhoto('apparatus',{distance:20,title:t.title,stateLabel:'RP preparation · physical school work still required'});valid=()=>v.practicalVariable==='light'&&v.practicalControls==='match'&&v.practicalMeasure==='repeat'&&v.practicalSafety==='safe';help='Change light while controlling confounders; acclimatise and repeat timed measurements. Appropriate safe equipment and supervision remain school practical requirements.';}
else if(t.type==='collect'){v.distance??=10;v.runs??={};body='<p>Original simulated measurements: each repeat collects oxygen for2min after acclimatisation. Other conditions matched. Record means and rates at all4 distances.</p>'+field('pondDistance','Lamp distance / cm',[10,20,30,40].map(d=>[d,d]),v.distance)+field('pondPrediction','Compared with40cm, predict this original comparison',[['faster','Greater oxygen rate at this nearer setting'],['same','Same40cm baseline']],v.pondPrediction)+'<button class="secondary" id="measurePond">Measure next2min repeat (simulated) →</button><p id="photoReadout"></p>'+number('meanVolume','Mean collected volume / cm³',v.meanVolume)+number('trialRate','Rate / cm³ per min',v.trialRate);draw=()=>{let count=v.runs[v.distance]||0,readings=pondTrials[v.distance].slice(0,count),last=readings.at(-1)||0;showPhoto('apparatus',{distance:v.distance,volume:last,title:t.title,stateLabel:v.distance+'cm · '+count+'/3 repeats'});$('#photoReadout').textContent=readings.length?'Volumes/cm³: '+readings.join(', ')+' · each over2min.':'Predict before the first repeat.';};record=()=>{let a=pondTrials[v.distance];if(v.runs[v.distance]!==3||v.pondPrediction!==(v.distance===40?'same':'faster')||!near(v.meanVolume,mean(a))||!near(v.trialRate,gasRate(mean(a),2))){feedback('Collect all3 timed repeats. Mean=sum÷3; rate=mean volume÷2min. Keep volume and rate units distinct.',true);return false;}if(!v.seen.includes(v.distance))v.seen.push(v.distance);return true;};valid=()=>[10,20,30,40].every(d=>v.seen.includes(d));help='Record all4 distances with3 repeats each. Original data illustrate a trend, not a calibrated inverse-square biological response.';}
else{v.plot??=['','','',''];body='<p>Construct from the completed original rate record:</p>'+photoTable(['Distance/cm','Rate/cm³ min⁻¹'],pondRates)+pondRates.map(([x],i)=>number('plot'+i,'Plot rate at'+x+'cm',v.plot[i])).join('')+field('photoAxes','Axes and suitable scale',[['correct','x: distance/cm; y: rate/cm³ min⁻¹;0–6'],['wrong','Call distance light intensity; no units']],v.photoAxes)+field('graphConclusion','Supported conclusion',[['range','Closer lamp gave higher rates in this dataset'],['forever','The same rate law holds for every organism']],v.graphConclusion);draw=()=>showPhoto('graph',{points:pondRates.map(([x],i)=>[x,v.plot[i]]).filter(([,y])=>y!==''&&Number.isFinite(Number(y))).map(([x,y])=>[x,Number(y)]),title:t.title});valid=()=>pondRates.every(([,y],i)=>near(v.plot[i],y))&&v.photoAxes==='correct'&&v.graphConclusion==='range';help='Plot6,4,2,1 at10,20,30,40cm with units and a suitable scale. It is a constrained graph task; do not relabel measured distance as intensity.';}
root.innerHTML=`<p><b>${index+1} / ${tasks.length} · ${t.title}</b></p>${body}<p id="photoEvidence"></p><div class="model-actions"><button class="secondary" id="recordPhoto">Record reasoning</button><button class="secondary" id="nextPhoto">Next challenge →</button></div><p id="photoProgress">${w.photoPassed.length} / ${tasks.length} complete</p>`;const remount=()=>mountPhoto(l,p,root,{save,done,feedback}),click=(id,fn)=>{if($('#'+id))$('#'+id).onclick=fn;},evidence=()=>{$('#photoEvidence').textContent=t.type==='compare'?'Recorded: '+t.states.map((s,i)=>(v.seen.includes(i)?'✓ ':'○ ')+s[1]).join(' · '):v.seen.length?'Recorded comparisons: '+v.seen.join(', '):'';};
for(let el of root.querySelectorAll('select,input'))el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='photoState'){v.state=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='photoPrediction')v.answer=val;else if(id==='factorIndex'){v.factorIndex=Number(val||2);v.factorPrediction='';delete v.factorRevealed;save();remount();return;}else if(['lampDistance','pondDistance'].includes(id)){v.distance=Number(val||10);v.inverseValue='';delete v.inverseRevealed;v.meanVolume='';v.trialRate='';v.pondPrediction='';save();remount();return;}else if(id==='greenhousePlan')v.plan=val||'baseline';else if(id.startsWith('plot'))v.plot[Number(id.slice(4))]=val;else v[id]=val;save();draw();};
for(let el of root.querySelectorAll('input[type=number]'))el.oninput=e=>{let id=e.target.id;if(id.startsWith('plot'))v.plot[Number(id.slice(4))]=e.target.value;else v[id]=e.target.value;save();if(id.startsWith('plot'))draw();};
click('revealPhoto',()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.state;save();draw();feedback(validPhotoAnswer(t,v.state,v.answer)?'Prediction agrees; record the evidence.':help,!validPhotoAnswer(t,v.state,v.answer));});click('revealLedger',()=>{if(!conservedPhoto(Number(v.coefCO2),Number(v.coefWater),Number(v.coefGlucose),Number(v.coefOxygen))||v.reactionEnergy!=='energy'){feedback(help,true);return;}v.ledgerRevealed=true;save();draw();});
click('revealFactor',()=>{if(!v.factorPrediction){feedback('Predict before revealing.',true);return;}v.factorRevealed=v.factorIndex;save();draw();});click('revealInverse',()=>{if(v.inverseValue===undefined||v.inverseValue===''){feedback('Calculate a predicted intensity first.',true);return;}v.inverseRevealed=v.distance;save();draw();});click('inspectPlan',()=>{if(!v.seen.includes(v.plan))v.seen.push(v.plan);save();draw();evidence();feedback('Plan evidence recorded.');});click('measurePond',()=>{if(!v.pondPrediction){feedback('Predict the comparison before measuring.',true);return;}v.runs[v.distance]=Math.min(3,(v.runs[v.distance]||0)+1);save();draw();});
$('#recordPhoto').onclick=()=>{if(record()===false)return;save();evidence();if(!valid()){feedback(help+' Complete the required comparisons/values.',true);return;}if(!w.photoPassed.includes(index))w.photoPassed.push(index);if(w.photoPassed.length===tasks.length){p.widgetDone=true;done();}save();$('#photoProgress').textContent=w.photoPassed.length+' / '+tasks.length+' complete';feedback('Evidence and reasoning recorded. '+help);};$('#nextPhoto').onclick=()=>{if(!w.photoPassed.includes(index)){feedback('Complete this challenge first.',true);return;}w.photoTask=(index+1)%tasks.length;save();feedback('');remount();};draw();evidence();}
